fun modInverseUtil(a: Long, m: Long): Long {
    var t = 0L
    var newT = 1L
    var r = m
    var newR = a
    while (newR != 0L) {
        val quotient = r / newR
        var tmp = newT
        newT = t - quotient * newT
        t = tmp
        tmp = newR
        newR = r - quotient * newR
        r = tmp
    }
    if (r > 1) {
        throw IllegalArgumentException("a is not invertible")
    }
    if (t < 0) {
        t += m
    }
    return t
}

fun gcd(a: Long, b: Long): Long {
    var a = a
    var b = b
    while (b > 0) {
        val t = b
        b = a % b
        a = t
    }
    return a
