fun modInverse(a: Long, p: Int): Long {
    return modPow(a, (p - 2).toLong(), p)
}

fun modPow(base: Long, exp: Long, mod: Int): Long {
    var result = 1L
    var b = base % mod
    var e = exp
    while (e > 0) {
        if (e % 2 == 1L) {
            result = (result * b) % mod
        }
        b = (b * b) % mod
        e /= 2
    }
    return result
}
